  --sd-color-text-success: var(--sd-ref-palette-green-700);
  --sd-color-text-warning: var(--sd-ref-palette-amber-700);
  --sd-color-text-info: var(--sd-ref-palette-blue-700);
  --sd-color-text-on-error: var(--sd-ref-palette-gray-000);
  --sd-color-text-emphasis: var(--sd-ref-palette-indigo-750);
  --sd-color-text-urgency: var(--sd-ref-palette-red-700);

    /* icon */
  --sd-color-icon-muted: var(--sd-ref-palette-gray-750);
  --sd-color-icon-rating: var(--sd-ref-palette-amber-550);

    /* fill */
  --sd-color-fill-brand: var(--sd-ref-palette-indigo-700);
  --sd-color-fill-accent: var(--sd-ref-palette-indigo-700);
  --sd-color-fill-destructive: var(--sd-ref-palette-red-650);
  --sd-color-fill-neutral-strong: var(--sd-ref-palette-gray-700);
  --sd-color-fill-error: var(--sd-ref-palette-red-650);
  --sd-color-fill-info: var(--sd-ref-palette-blue-350);
  --sd-color-fill-live: var(--sd-ref-palette-red-650);
  --sd-color-fill-category-1: var(--sd-ref-palette-indigo-700);
  --sd-color-fill-category-2: var(--sd-ref-palette-orange-650);
  --sd-color-fill-category-3: var(--sd-ref-palette-green-650);
  --sd-color-fill-category-4: var(--sd-ref-palette-red-650);
  --sd-color-fill-category-5: var(--sd-ref-palette-purple-650);
  --sd-color-fill-category-6: var(--sd-ref-palette-teal-650);
  --sd-color-fill-category-7: var(--sd-ref-palette-pink-650);
  --sd-color-fill-category-8: var(--sd-ref-palette-yellow-650);

    /* surface */
  --sd-color-surface-overlay-translucent: var(--sd-ref-palette-white-alpha-900);

    /* border */
  --sd-color-border: var(--sd-ref-palette-gray-650);
  --sd-color-border-subtle: var(--sd-ref-palette-gray-350);
  --sd-color-border-strong: var(--sd-ref-palette-gray-700);
