  --sd-color-border-invalid: var(--sd-ref-palette-red-550);
  --sd-color-border-focus: var(--sd-ref-palette-indigo-600);
  --sd-color-border-inverse: var(--sd-ref-palette-gray-550);
  --sd-color-border-brand: var(--sd-ref-palette-indigo-600);
  --sd-color-border-accent: var(--sd-ref-palette-indigo-600);
  --sd-color-border-error: var(--sd-ref-palette-red-550);
  --sd-color-border-error-subtle: var(--sd-ref-palette-red-450);
  --sd-color-border-success: var(--sd-ref-palette-green-550);
