  --sd-color-border-warning: var(--sd-ref-palette-amber-550);
  --sd-color-border-warning-subtle: var(--sd-ref-palette-amber-450);
  --sd-color-border-info: var(--sd-ref-palette-blue-550);
  --sd-color-border-info-subtle: var(--sd-ref-palette-blue-450);
  --sd-color-border-decorative: var(--sd-ref-palette-alpha-450);
  --sd-color-border-category-1: var(--sd-ref-palette-indigo-600);
  --sd-color-border-category-2: var(--sd-ref-palette-orange-550);
  --sd-color-border-category-3: var(--sd-ref-palette-green-550);
  --sd-color-border-category-4: var(--sd-ref-palette-red-550);
  --sd-color-border-category-5: var(--sd-ref-palette-purple-550);
  --sd-color-border-category-6: var(--sd-ref-palette-teal-550);
  --sd-color-border-category-7: var(--sd-ref-palette-pink-550);
  --sd-color-border-category-8: var(--sd-ref-palette-yellow-550);

    /* selection */
  --sd-color-selection-foreground: var(--sd-ref-palette-gray-750);

    /* hover */
  --sd-state-hover-on-error: var(--sd-ref-palette-alpha-100);

    /* pressed */
  --sd-state-pressed-on-error: var(--sd-ref-palette-alpha-150);

    /* focus-ring */
  --sd-state-focus-ring: var(--sd-ref-palette-indigo-600);
  }
}

/* Inverse ground — "translucent" surface treatment, re-declared so it resolves against the swapped roles */
html:root[data-brand="aronia"][data-surface="translucent"] [data-ground="inverse"] {
  --sd-surface-treatment-overlay-background: var(--sd-color-surface-overlay-translucent);
}
